import {createGame,updateGame,VIEW,clamp} from './engine.mjs';
export const SUCCESS_MESSAGES=['進捗が生まれた！','完璧なコードを書いた！','実験が想定通り100パーセントの結果で出た！','一発で論文が採択された！','締切前にレポートが完成した！'];
export const FEVER_CONFIG={intro:4.4,outro:4.8,speed:610,attackCooldown:.7,pulseDuration:.22,attackRadius:230,comboWindow:4,effectScale:1,width:15400};
export function createFever(snapshot=null){
 const width=FEVER_CONFIG.width,L={id:9,name:'虹色オーバードライブ',en:'FEVER OVERDRIVE',theme:'fever',color:'#ffda80',location:'777 / FEVER OVERDRIVE',tagline:'無敵の夜勤！ 走って、跳んで、Xで一気に撃破。',tip:'無敵！ ← → で移動、SPACE で二段ジャンプ、X で連射パルス。自分の操作でゴールへ！',width,minY:-120,killY:800,spawn:{x:100,y:470},platforms:[{x:0,y:510,w:width,h:180,type:'ground'}],enemies:[],chips:[],gears:[],drinks:[],winds:[],lasers:[],relays:[],signs:[],students:[],checkpoints:[],presses:[],gravityZones:[],portals:[],rails:[],route:[],goal:{x:width-170,y:510}};
 for(let x=650;x<width-450;x+=460){for(let j=0;j<3;j++){const ex=x+j*85;L.enemies.push({x:ex,y:482,baseY:482,w:32,h:28,min:ex-35,max:ex+35,speed:48,dir:-1,alive:true,kind:['resistor','capacitor','chip','beaker','diode'][Math.floor(x/460)%5],clock:0,state:'patrol',stateTime:0});}for(let j=0;j<5;j++)L.chips.push({x:x+j*45,y:465});L.route.push({x,y:510});}
 for(let x=1800;x<width-800;x+=2800){L.platforms.push({x,y:400,w:250,h:20,type:'platform'},{x:x+280,y:300,w:420,h:20,type:'platform'});for(let j=0;j<10;j++)L.chips.push({x:x+300+j*38,y:255});L.enemies.push({x:x+430,y:272,baseY:272,w:32,h:28,min:x+330,max:x+600,speed:40,dir:1,alive:true,kind:'chip',clock:0,state:'patrol',stateTime:0});}
 const g=createGame(0,L);g.fever={...FEVER_CONFIG,combo:0,best:0,kills:0,comboTimer:0,label:'',labelTimer:0,impact:0,trail:[],demo:false};g.player.invul=999;
 if(snapshot){g.player.x=clamp(Number(snapshot.x)||100,0,width-230);g.player.y=clamp(Number(snapshot.y)||470,-120,470);g.elapsed=Math.max(0,Number(snapshot.elapsed)||0);g.fever.kills=Math.max(0,Number(snapshot.kills)||0);g.fever.best=Math.max(0,Number(snapshot.best)||0);for(const i of snapshot.dead||[])if(g.level.enemies[i])g.level.enemies[i].alive=false;for(const i of snapshot.chips||[])if(g.level.chips[i])g.level.chips[i].got=true;g.chips=g.level.chips.filter(c=>c.got).length;g.camera=clamp(g.player.x-VIEW.w*.32,0,width-VIEW.w);}
 return g;
}
export function feverSnapshot(g){return {x:g.player.x,y:g.player.y,elapsed:g.elapsed,kills:g.fever.kills,best:g.fever.best,dead:g.level.enemies.flatMap((e,i)=>e.alive?[]:[i]),chips:g.level.chips.flatMap((c,i)=>c.got?[i]:[])};}
export function updateFever(g,input,dt){
 const f=g.fever;f.labelTimer=Math.max(0,f.labelTimer-dt);f.impact=Math.max(0,f.impact-dt);f.comboTimer=Math.max(0,f.comboTimer-dt);if(f.comboTimer===0)f.combo=0;
 const fire=input.pulse&&g.cooldown<=0;updateGame(g,input,dt);
 if(fire)for(const e of g.level.enemies)if(e.alive&&Math.hypot(e.x-g.player.x,e.y-g.player.y)<f.attackRadius){e.alive=false;g.events.push({type:'feverKill',x:e.x+16,y:e.y+14});}
 for(const e of g.events)if(e.type==='feverKill'){f.combo++;f.kills++;f.best=Math.max(f.best,f.combo);f.comboTimer=f.comboWindow;f.impact=.3;if(f.combo%5===0||f.combo===1){f.label=['GREAT!!','SUPER!!','EXCELLENT!!','FEVER!!','大当たり!!'][Math.min(4,Math.floor(f.combo/10))];f.success=SUCCESS_MESSAGES[Math.floor(f.kills/5)%SUCCESS_MESSAGES.length];f.labelTimer=1.5;g.events.push({type:'feverMilestone',combo:f.combo});}}
 f.trail.push({x:g.player.x,y:g.player.y,life:.22});for(const p of f.trail)p.life-=dt;f.trail=f.trail.filter(p=>p.life>0).slice(-12);
}
const logos=new Map();
function logoTexture(text){
 if(logos.has(text))return logos.get(text);const cv=document.createElement('canvas');cv.width=1300;cv.height=240;const c=cv.getContext('2d');c.textAlign='center';c.textBaseline='middle';c.lineJoin='round';let size=text.length>12?112:145;c.font=`1000 ${size}px Arial Black, Impact, sans-serif`;const m=c.measureText(text).width;if(m>1140){size*=1140/m;c.font=`1000 ${size}px Arial Black, Impact, sans-serif`;}
 const x=635,y=104;c.shadowColor='#e29c0f';c.shadowBlur=24;c.strokeStyle='#ffdc75';c.lineWidth=32;c.strokeText(text,x+17,y+22);c.shadowBlur=0;
 for(let i=23;i>=1;i--){c.fillStyle=i%5===0?'#ffe4a4':i%5===1?'#9c671b':'#56341e';c.strokeStyle=c.fillStyle;c.lineWidth=20;c.strokeText(text,x+i*.7,y+i);c.fillText(text,x+i*.7,y+i);}
 const gold=c.createLinearGradient(0,35,0,180);[[0,'#fffbe3'],[.23,'#ffe59a'],[.47,'#9e5b07'],[.5,'#fff4ba'],[.75,'#e49f24'],[1,'#6f3805']].forEach(([p,v])=>gold.addColorStop(p,v));c.lineWidth=25;c.strokeStyle=gold;c.strokeText(text,x,y);
 c.lineWidth=15;c.strokeStyle='#281e43';c.strokeText(text,x,y);const silver=c.createLinearGradient(0,30,0,160);silver.addColorStop(0,'#fff');silver.addColorStop(.45,'#bac6ef');silver.addColorStop(.5,'#455879');silver.addColorStop(.8,'#fff');c.strokeStyle=silver;c.lineWidth=10;c.strokeText(text,x,y);c.lineWidth=3;c.strokeStyle='#fff';c.strokeText(text,x,y);
 const rainbow=c.createLinearGradient(100,30,1180,180);['#ff5a87','#ffca38','#fbff91','#2eefa9','#38a4ff','#d28bff','#ff5c97','#ffe56c'].forEach((col,i)=>rainbow.addColorStop(i/7,col));c.fillStyle=rainbow;c.fillText(text,x,y);
 c.save();c.globalCompositeOperation='source-atop';const gloss=c.createLinearGradient(0,30,0,180);gloss.addColorStop(0,'#fff0');gloss.addColorStop(.25,'#ffffffb0');gloss.addColorStop(.48,'#fff0');gloss.addColorStop(.5,'#24234465');gloss.addColorStop(.7,'#fff0');c.fillStyle=gloss;c.fillRect(0,20,1300,165);c.restore();const mask=document.createElement('canvas');mask.width=cv.width;mask.height=cv.height;const mc=mask.getContext('2d');mc.font=c.font;mc.textAlign='center';mc.textBaseline='middle';mc.fillStyle='white';mc.fillText(text,x,y);cv.faceMask=mask;cv.sheen=document.createElement('canvas');cv.sheen.width=cv.width;cv.sheen.height=cv.height;logos.set(text,cv);return cv;
}
export function drawMetalText(c,text,x,y,width,t,alpha=1){const img=logoTexture(text),h=width*img.height/img.width;c.save();c.globalAlpha=alpha;c.drawImage(img,x-width/2,y-h/2,width,h);const sc=img.sheen.getContext('2d'),sx=(t*.45%1)*1700-200;sc.clearRect(0,0,1300,240);sc.globalCompositeOperation='source-over';sc.drawImage(img.faceMask,0,0);sc.globalCompositeOperation='source-in';const sheen=sc.createLinearGradient(sx,0,sx+170,240);sheen.addColorStop(0,'#fff0');sheen.addColorStop(.48,'#ffffff00');sheen.addColorStop(.55,'#fffbdcbd');sheen.addColorStop(.62,'#ffffff00');sheen.addColorStop(1,'#fff0');sc.fillStyle=sheen;sc.fillRect(0,0,1300,240);c.drawImage(img.sheen,x-width/2,y-h/2,width,h);const spark=x-width*.36+(t*.25%1)*width*.72;for(const [sx,sy,r] of [[spark,y-h*.15,9],[x+width*.35,y+h*.17,6]]){c.fillStyle='#fffbed';c.beginPath();c.moveTo(sx-r,sy);c.lineTo(sx-2,sy-2);c.lineTo(sx,sy-r);c.lineTo(sx+2,sy-2);c.lineTo(sx+r,sy);c.lineTo(sx+2,sy+2);c.lineTo(sx,sy+r);c.lineTo(sx-2,sy+2);c.closePath();c.fill();}c.restore();}
function rays(c,w,h,t,power,reduced){c.save();c.translate(w/2,h*.45);for(let i=0;i<24;i++){c.rotate(Math.PI/12);c.fillStyle=`hsla(${i*28+t*(reduced?0:16)},95%,65%,${.025+power*.018})`;c.beginPath();c.moveTo(0,0);c.lineTo(-32,-w);c.lineTo(55,-w);c.closePath();c.fill();}c.restore();}
export function drawFeverIntro(c,age,reduced=false,outro=false,stats=null){const w=VIEW.w,h=600;c.fillStyle='#0c061d';c.fillRect(0,0,w,h);if(age<.25&&!outro)return;const t=age,entrance=clamp((age-.38)/.65,0,1),scale=reduced?1:Math.min(1.08,entrance*1.12);rays(c,w,h,t,8,reduced);
 c.save();c.strokeStyle='#e4b965';c.lineWidth=2;c.strokeRect(18,18,w-36,h-36);c.strokeStyle='#fff0ba55';c.lineWidth=5;c.strokeRect(27,27,w-54,h-54);
 c.textAlign='center';c.font='900 160px Arial Black, sans-serif';c.fillStyle='#ffd47a0c';c.fillText('777',w/2,175);c.font='bold 12px monospace';c.fillStyle='#e9c985';c.fillText('✦  MIDNIGHT CIRCUIT  /  GOLDEN REPAIR CHANCE  ✦',w/2,65);
 for(const side of [-1,1]){c.save();c.translate(w/2+side*w*.39,270);c.rotate(side*.18);for(let i=0;i<3;i++){c.strokeStyle=['#b77b2c','#fff1a8','#8a4d12'][i];c.lineWidth=3;c.beginPath();c.arc(0,0,74+i*7,-1.2,1.2);c.stroke();}c.restore();}
 c.restore();
 for(let i=0;i<(reduced?25:95);i++){const a=i*2.399,r=((t*115+i*37)%690),x=w/2+Math.cos(a)*r,y=270+Math.sin(a)*r*.66;c.fillStyle=i%4?'#ffda92':'#fff5e8';c.globalAlpha=.25+(i%7)/10;c.fillRect(x,y,2+i%4,2+i%4);}c.globalAlpha=1;
 c.save();if(!reduced&&age>.7&&age<1.15)c.translate(Math.sin(age*85)*7,Math.cos(age*97)*4);drawMetalText(c,outro?'BONUS CLEAR!!':'FEVER!!',w/2,255,Math.min(w*.94,1150)*scale*(outro?1:1.3),t);c.restore();
 if(age>.95){c.textAlign='center';c.fillStyle='#ffe4a0';c.font='bold 18px sans-serif';c.fillText(outro?'圧倒的、修理大成功。':'BONUS STAGE · 虹色オーバードライブ',w/2,362);c.fillStyle='#eee5ff';c.font='13px sans-serif';c.fillText(outro?`${stats?.kills||0} 撃破   /   MAX ${stats?.best||0} COMBO`:'無敵 × 高速ダッシュ × 連射パルス',w/2,398);c.fillStyle='#aa9abb';c.font='11px sans-serif';c.fillText(outro?'通常コースの進行に戻ります':'← → 移動    SPACE 二段ジャンプ    X 攻撃',w/2,441);}
 if(!reduced&&age>.28&&age<.48){c.fillStyle=`rgba(255,239,190,${(.48-age)*3})`;c.fillRect(0,0,w,h);}
}
export function drawFeverFX(c,g,t,reduced){const f=g.fever,w=VIEW.w,power=Math.min(5,1+f.combo/15)*f.effectScale;rays(c,w,600,t,power,reduced);
 c.save();c.translate(-g.camera,-g.cameraY);if(!reduced){for(const a of f.trail){c.fillStyle=`hsla(${t*160+a.x},100%,65%,${a.life*.6})`;c.fillRect(a.x-5,a.y+5,32,32);}for(let i=0;i<12;i++){c.strokeStyle=`hsla(${i*30+t*50},100%,75%,.25)`;c.beginPath();const x=g.camera+(i*137-t*600)%w;c.moveTo(x,180+i*24);c.lineTo(x+80+power*10,180+i*24);c.stroke();}}c.restore();
 for(let i=0;i<Math.ceil(w/28);i++){c.fillStyle=`hsl(${i*20+(reduced?0:t*50)},95%,${50+Math.sin(i+t*3)*10}%)`;c.fillRect(i*28,3,18,4);c.fillRect(i*28,590,18,4);}for(let y=20;y<590;y+=28){c.fillStyle=y%56?'#ffd892':'#fbd4ff';c.fillRect(3,y,4,18);c.fillRect(w-7,y,4,18);}
 c.textAlign='right';c.fillStyle='#ffdf90';c.font='900 30px sans-serif';c.fillText(`${f.combo} COMBO`,w-30,130);c.fillStyle='#fff2cc';c.font='11px monospace';c.fillText(`BEST ${f.best}  /  ${f.kills} KOs`,w-32,152);c.fillStyle='#ffd48c';c.fillRect(w-175,163,145*f.comboTimer/f.comboWindow,3);
 if(f.labelTimer>0){const a=Math.min(1,f.labelTimer*4),size=Math.min(w*.66,650)*(reduced?1:1+(1-f.labelTimer)*.05*power);drawMetalText(c,f.label,w/2,190,size,t,a);c.textAlign='center';c.font='bold 19px sans-serif';c.fillStyle='#fff3bd';c.fillText(f.success||SUCCESS_MESSAGES[0],w/2,250,w*.9);}
}
